<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Product_Search{
 public function search(array|string $request,int $legacy_limit=6):array{if(!function_exists('wc_get_products'))return array();$args=is_array($request)?$request:array('query'=>$request,'limit'=>$legacy_limit);$query=sanitize_text_field((string)($args['query']??''));$role=sanitize_key((string)($args['role']??''));$limit=max(1,min(20,absint($args['limit']??12)));$in_stock=!isset($args['in_stock'])||filter_var($args['in_stock'],FILTER_VALIDATE_BOOLEAN);$tokens=$this->keywords($query);if(!$tokens)return array();$index_matches=(new Orion_Product_Index())->search($query,60);$ids=array_map('absint',array_keys($index_matches));$base=array('status'=>'publish','visibility'=>'visible','limit'=>30,'return'=>'ids');if($in_stock)$base['stock_status']=array('instock','onbackorder');$exact=$base;$exact['search']=$query;$ids=array_merge($ids,array_map('absint',wc_get_products($exact)));foreach(array_slice($tokens,0,8)as$token){$q=$base;$q['search']=$token;$ids=array_values(array_unique(array_merge($ids,array_map('absint',wc_get_products($q)))));if(count($ids)>=100)break;}$category_ids=$this->category_candidates($tokens,$base);$ids=array_values(array_unique(array_merge($ids,$category_ids)));$broad=array_fill_keys(array_merge(array_map('absint',array_keys($index_matches)),$category_ids),true);$sku=wc_get_product_id_by_sku($query);if($sku)$ids[]=(int)$sku;$scored=array();foreach(array_unique($ids)as$id){$item=$this->get_product((int)$id);if(!$item||($in_stock&&!$item['in_stock']))continue;$score=$this->score($item,$tokens,$query,$role);$source='woocommerce_search';if(isset($index_matches[$id])){$source=$index_matches[$id]['source'];$score=max($score,1+(int)round((float)$index_matches[$id]['score']*10));}elseif(in_array($id,$category_ids,true)){$source='category_recall';$score=max($score,1);}if($score<1||(!isset($broad[$id])&&$score<1))continue;$item['retrieval']=array('source'=>$source,'score'=>$score);$scored[]=array('score'=>$score,'item'=>$item);}usort($scored,static fn($a,$b)=>$b['score']<=>$a['score']);return array_values(array_map(static fn($row)=>$row['item'],array_slice($scored,0,$limit)));}
 public function get_product(int $id):?array{if(!function_exists('wc_get_product')||$id<1)return null;try{$p=wc_get_product($id);return(!$p||!$p->is_visible())?null:$this->format($p);}catch(Throwable $e){error_log('Orion AI product lookup failed for '.absint($id));return null;}}
 private function category_candidates(array $tokens,array $base):array{$terms=get_terms(array('taxonomy'=>'product_cat','hide_empty'=>true));if(is_wp_error($terms))return array();$slugs=array();foreach($terms as$term){$hay=strtolower($term->name.' '.$term->slug);foreach($tokens as$token)if(strlen($token)>3&&str_contains($hay,$token)){$slugs[]=$term->slug;break;}}$ids=array();foreach(array_slice(array_unique($slugs),0,8)as$slug){$q=$base;$q['category']=array($slug);$q['limit']=80;$ids=array_merge($ids,array_map('absint',wc_get_products($q)));if(count($ids)>=160)break;}return array_values(array_unique($ids));}
 private function score(array $item,array $tokens,string $query,string $role):int{$name=strtolower($item['name']);$cats=strtolower(implode(' ',$item['categories']));$desc=strtolower((string)($item['description']??$item['short_description']));$attrs=strtolower(wp_json_encode($item['attributes']));$hay=$name.' '.$cats.' '.$desc.' '.$attrs;$matched=0;$score=0;foreach($tokens as$t)if(str_contains($hay,$t)){$matched++;$score+=str_contains($name,$t)?4:(str_contains($cats,$t)?3:1);}if($matched<min(2,count($tokens)))return 0;$core=!in_array($role,array('roller','roller_sleeve','roller_frame','brush','tray','tool','cleaner','masking_tape','dust_sheet','sandpaper','scraper'),true);$special=array('floor','garage','epoxy','tile','masonry','exterior','outdoor','ceiling','primer');$required=array_values(array_intersect($tokens,$special));if($core&&$required&&!array_filter($required,static fn($t)=>str_contains($hay,$t)))return 0;if((str_contains(strtolower($query),'floor')||str_contains(strtolower($query),'garage'))&&preg_match('/walls? and ceilings?|walls?|ceilings?/',$desc)&&!preg_match('/floor|garage|epoxy/',$hay))return 0;return$score;}
 private function keywords(string $text):array{$stop=array('what','which','with','that','this','from','have','need','show','find','looking','please','would','could','product','products','for','the','and','are','you','your','some','best','high','area','durable','suitable','coverage','compatible','selected','where','needed','small','finish');$map=array('matte'=>'matt','ceilings'=>'ceiling','walls'=>'wall','painting'=>'paint','interior'=>'internal');$tokens=preg_split('/[^a-z0-9-]+/i',strtolower($text))?:array();$out=array();foreach($tokens as$t){$t=$map[$t]??$t;if(strlen($t)>2&&!in_array($t,$stop,true))$out[]=$t;}return array_values(array_unique($out));}
 private function format(WC_Product $p):array{$attrs=array();foreach(array_slice($p->get_attributes(),0,12)as$a){if($a->is_taxonomy()){$values=wc_get_product_terms($p->get_id(),$a->get_name(),array('fields'=>'names'));$label=wc_attribute_label($a->get_name());}else{$values=$a->get_options();$label=$a->get_name();}if(!is_wp_error($values)&&$values)$attrs[$label]=array_values(array_map('strval',$values));}$terms=wp_get_post_terms($p->get_id(),'product_cat');$cats=array();$category_links=array();if(!is_wp_error($terms)){foreach($terms as$term){$name=(string)$term->name;$cats[]=$name;$url=get_term_link($term);if(!is_wp_error($url))$category_links[]=array('name'=>$name,'url'=>(string)$url);}}$html=$p->get_price_html();$short=trim(wp_strip_all_tags($p->get_short_description()));$long=trim(wp_strip_all_tags($p->get_description()));$description=mb_substr(trim($short.' '.$long),0,1200);$item=array('id'=>$p->get_id(),'sku'=>$p->get_sku(),'name'=>$p->get_name(),'type'=>$p->get_type(),'url'=>$p->get_permalink(),'image'=>wp_get_attachment_image_url($p->get_image_id(),'woocommerce_thumbnail')?:wc_placeholder_img_src('woocommerce_thumbnail'),'price_text'=>html_entity_decode(trim(wp_strip_all_tags($html)),ENT_QUOTES|ENT_HTML5,get_bloginfo('charset')?:'UTF-8'),'price'=>$p->get_price(),'in_stock'=>$p->is_in_stock(),'stock_status'=>$p->get_stock_status(),'short_description'=>mb_substr($short,0,500),'description'=>$description,'categories'=>array_values($cats),'category_links'=>array_values($category_links),'attributes'=>$attrs,'can_add_to_cart'=>$p->is_type('simple')&&$p->is_purchasable()&&$p->is_in_stock());if($p->is_type('variable')){$item['variation_attributes']=$p->get_variation_attributes();$item['variation_count']=count($p->get_children());}return$item;}
}
